def enclosing_func(path, lineno):
    with open(path) as f:
        lines = f.readlines()
    # search backward for def or class at lesser or equal indentation forming enclosing function
    target_indent = None
    for i in range(lineno-1, -1, -1):
        line = lines[i]
        stripped = line.lstrip()
        if not stripped.strip():
            continue
        indent = len(line) - len(stripped)
        m = re.match(r'def (\w+)', stripped)
        if m and (target_indent is None or indent < target_indent):
            return m.group(1)
